"function rnd(a,b){return Math.random()*(b-a)+a} function getNextResult(){return (patternCounter%10)<9;}",
"function checkHourlyReset(){var now=Date.now();var hourElapsed=now-hourStart;if(hourElapsed>=3600000){tradesHour=0;hourStart=now;lastHourlyReset=now;document.getElementById('hourInfo').innerText=\"Hourly Info: Hourly RESET DONE! Trades reset to 0/5 | Next reset in 60min | 24H Trading Active | V36 Fix - No More Stuck - Last reset: \"+new Date().toLocaleTimeString();return true;}var remaining=3600000-hourElapsed;var mins=Math.floor(remaining/60000);var secs=Math.floor((remaining%60000)/1000);document.getElementById('hourInfo').innerText=\"Hourly Info: Hour active \"+Math.floor(hourElapsed/60000)+\"min | Trades this hour \"+tradesHour+\"/5 | Next reset in \"+mins+\"m \"+secs+\"s | 24H Trading Active | V36 Fix\";return false;}",
"function canStart(){if(tradeActive)return false;if(currBal<250)return false;checkHourlyReset();if(tradesHour>=5){var remaining=3600000-(Date.now()-hourStart);var mins=Math.ceil(remaining/60000);return false;}if(lastTrade!=0&&Date.now()-lastTrade<cooldownDuration){return false;}return true;}",
"function startTrade(isManual){if(!canStart()&&!isManual){return;}if(tradesHour>=5&&!isManual){return;}tradeActive=true;tradeStartTime=Date.now();tradeEndTime=tradeStartTime+fixedDuration;document.getElementById('tradeStatus').innerText='TRADE RUNNING - RSI '+rsi.toFixed(1)+' + Vol High + ATR '+atr.toFixed(2)+' + VWAP Bull + MACD Bull - 60s - V36 5 Trade Fix - 24H';document.getElementById('tradeStatus').className='trade-status status-running';}",
"function forceTrade(){tradesHour=0;lastTrade=0;tradeActive=false;hourStart=Date.now();alert('FORCE TRADE - V36 Fix - Reset all - Trading now!');startTrade(true);}",
"function closeTrade(){var isWin=getNextResult();patternCounter++;var p=isWin?rnd(280,400):rnd(-40,-80);currBal+=p;totalPL+=p;priceHistory.push(currBal);if(priceHistory.length>20)priceHistory.shift();if(isWin)wins++;else losses++;tradesHour++;lastTrade=Date.now();tradeActive=false;var t=new Date().toLocaleTimeString();historyData.unshift({time:t,result:isWin?'WIN':'LOSS',profit:p.toFixed(0),bal:Math.floor(currBal)});if(historyData.length>30)historyData.pop();updateHistory();updateChart();}",
"function toggleAuto(){autoOn=!autoOn;var b=document.getElementById('autoBtn');b.innerText=autoOn?'AUTO ON - Bal '+Math.floor(currBal)+' - Profit '+Math.floor(totalPL)+' - V36 5 TRADE FIX - 24H - 90% WIN':'AUTO OFF - V36 5 TRADE FIX';}",
