"function updatePriceTicker(){btcPrice+=rnd(-80,80);rsi=rnd(55,68);vol=rnd(0.9,1.5);atr=rnd(1.1,1.4);vwap=btcPrice-rnd(-50,100);macd=rnd(0.3,0.6);document.getElementById('priceTicker').innerHTML='LIVE PRICE: BTC $'+btcPrice.toFixed(2)+' | V36 5 TRADE FIX - 24H - RSI '+rsi.toFixed(1)+' VOL '+vol.toFixed(1)+'M ATR '+atr.toFixed(2)+' VWAP '+vwap.toFixed(0)+' MACD +'+macd.toFixed(2)+' - 90% WIN - Trades '+tradesHour+'/5';checkHourlyReset();}",
"function updateChart(){var c=document.getElementById('chartCanvas');if(!c)return;var ctx=c.getContext('2d');var w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#000';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#222';ctx.lineWidth=0.5;for(var i=0;i<3;i++){var y=(i/3)*h;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}if(priceHistory.length<2)return;var max=Math.max.apply(null,priceHistory),min=Math.min.apply(null,priceHistory),range=max-min||1;ctx.beginPath();ctx.strokeStyle='#0F0';ctx.lineWidth=3;ctx.shadowColor='#0F0';ctx.shadowBlur=10;for(var i=0;i<priceHistory.length;i++){var p=priceHistory[i];var x=(i/(priceHistory.length-1))*w;var y=h-((p-min)/range)*h*0.7 - h*0.15;if(i==0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();ctx.shadowBlur=0;ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fillStyle='rgba(0,255,0,0.2)';ctx.fill();for(var i=0;i<priceHistory.length;i++){var p=priceHistory[i];var x=(i/(priceHistory.length-1))*w;var y=h-((p-min)/range)*h*0.7 - h*0.15;ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fillStyle=i==priceHistory.length-1?'#FFD700':'#0F0';ctx.fill();}}",
"function render(){var now=Date.now();checkHourlyReset();if(tradeActive){var e=now-tradeStartTime;if(e>65000){closeTrade();return;}var rem=Math.max(0,tradeEndTime-now);var prog=(e/fixedDuration)*100;document.getElementById('candleFill').style.width=Math.min(100,prog)+'%';document.getElementById('candleTimer').innerText='Candle: '+Math.ceil(rem/1000)+'s - '+Math.floor(prog)+'% - V36 5 Trade Fix - Auto Every 1 Min - Trades '+tradesHour+'/5 - 24H - 90% Win';if(rem<=0){closeTrade();return;}}else{var nextIn=lastTrade==0?0:Math.max(0,cooldownDuration-(Date.now()-lastTrade));if(tradesHour>=5){var remaining=3600000-(Date.now()-hourStart);var mins=Math.ceil(remaining/60000);document.getElementById('candleTimer').innerText='Candle: Hourly Limit 5/5 - Next reset in '+mins+'m - V36 Fix - 24H Trading - Trades '+tradesHour+'/5';}else if(nextIn>0){document.getElementById('candleTimer').innerText='Candle: Cooldown '+Math.ceil(nextIn/1000)+'s - Next trade soon - V36 Fix - Trades '+tradesHour+'/5 - 24H';}else{document.getElementById('candleTimer').innerText='Candle: Ready - V36 5 Trade Fix - Auto Every 1 Min - Trades '+tradesHour+'/5 - 24H - 90% Win';}document.getElementById('debugInfo').innerText='Debug: '+tradesHour+'/5 | '+(lastTrade==0?'Ready':Math.ceil(nextIn/1000)+'s cooldown')+' | Hourly Reset Active | Auto Every 1min | 24H Trading | V36 5 Trade Fix';confidence=getNextResult()?92:30;}document.getElementById('currentBal').innerText=Math.floor(currBal)+' PKR';document.getElementById('totalProfit').innerText=(totalPL>=0?'+':'')+Math.floor(totalPL)+' PKR';document.getElementById('todayProfit').innerText=(totalPL>=0?'+':'')+Math.floor(totalPL)+' PKR';document.getElementById('confidenceFill').style.width=confidence+'%';document.getElementById('confidenceText').innerText=confidence+'% - '+(confidence>80?'WIN Expected - V36 5 Trade Fix - 24H':'LOSS Expected')+' - 90% Win - Trades '+tradesHour+'/5';var total=wins+losses;var rate=total?Math.round(wins/total*100):90;document.getElementById('wins').innerText=wins;document.getElementById('loss').innerText=losses;document.getElementById('winRate').innerText=rate+'%';document.getElementById('tradeLimitText').innerText=tradesHour+'/5 TRADES/HOUR - '+wins+' WIN '+losses+' LOSS - 24H TRADING - V36 - Hourly Reset Every 60min - Auto Every 1 Min - '+rate+'% WIN';if(canStart()&&autoOn&&!tradeActive){startTrade(false);}}",
"function updateHistory(){var hDiv=document.getElementById('history');var html=\"\";for(var i=0;i<historyData.length;i++){var h=historyData[i];var col=h.result=='WIN'?'#0F0':'#F33';html+='<div style=\"display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #222\"><span>'+h.time+' '+h.result+' 250 RS - V36 5 Trade Fix - 90%</span><span style=\"color:'+col+';font-weight:900\">'+h.profit+' PKR | Bal '+h.bal+'</span></div>';}hDiv.innerHTML=html;}",
"function exportHistory(){var csv='Time,Result,Profit,Balance\\n';for(var i=0;i<historyData.length;i++){var h=historyData[i];csv+=h.time+','+h.result+','+h.profit+','+h.bal+'\\n';}var blob=new Blob([csv],{type:'text/csv'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='sona_v36_5trade_fix_24h_history.csv';a.click();}",
